{"file_path": "insertion_sort.cpp", "old_string": "", "new_string": "/**
 * 插入排序算法实现 (C++)
 * =====================
 * 
 * 核心思想：
 * 插入排序的工作原理类似于整理扑克牌。它将数组分为两个部分：已排序部分和未排序部分。
 * 初始时，已排序部分只包含数组的第一个元素，然后依次从未排序部分取出元素，
 * 在已排序部分找到合适的位置插入，直到所有元素都被排序。
 * 
 * 算法步骤：
 * 1. 从第一个元素开始，该元素可以认为已经被排序
 * 2. 取出下一个元素，在已经排序的元素序列中从后向前扫描
 * 3. 如果该元素（已排序）大于新元素，将该元素移到下一位置
 * 4. 重复步骤3，直到找到已排序的元素小于或者等于新元素的位置
 * 5. 将新元素插入到该位置后
 * 6. 重复步骤2~5，直到所有元素都排序完毕
 * 
 * 时间复杂度：
 * - 最佳情况：O(n) - 当输入数组已经有序时，只需遍历一次
 * - 最坏情况：O(n²) - 当输入数组是逆序时，需要进行 n(n-1)/2 次比较和移动
 * - 平均情况：O(n²) - 平均需要 n²/4 次比较和移动
 * 
 * 空间复杂度：
 * - O(1) - 原地排序算法，只需要常数级别的额外空间
 * 
 * 稳定性：
 * - 稳定排序算法 - 相等元素的相对顺序不会改变
 * 
 * 适用场景：
 * - 小规模数据集（n ≤ 1000）
 * - 数据基本有序
 * - 需要稳定排序
 * - 在线算法（数据逐个到达时可以即时排序）
 */

#include <iostream>
#include <vector>
#include <algorithm>
#include <iomanip>

/**
 * 基本插入排序（升序）
 * @param arr 待排序的数组
 */
template <typename T>
void insertionSort(std::vector<T>& arr) {
    int n = arr.size();

    // 从第二个元素开始遍历（第一个元素默认已排序）
    for (int i = 1; i < n; ++i) {
        // 记录当前待插入的元素
        T key = arr[i];

        // 从已排序部分的末尾开始向前扫描
        int j = i - 1;

        // 将大于 key 的元素向后移动
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j]; // 元素后移
            --j;
        }

        // 将 key 插入到正确位置
        arr[j + 1] = key;
    }
}

/**
 * 带详细步骤输出的插入排序（用于学习演示）
 * @param arr 待排序的数组
 */
template <typename T>
void insertionSortWithSteps(std::vector<T>& arr) {
    int n = arr.size();

    std::cout << "初始数组: ";
    printArray(arr);
    std::cout << std::string(50, '-') << std::endl;

    for (int i = 1; i < n; ++i) {
        T key = arr[i];
        int j = i - 1;

        std::cout << "第 " << i << " 轮: 将 " << key << " 插入到已排序部分 ";
        printArray(std::vector<T>(arr.begin(), arr.begin() + i));
        std::cout << std::endl;

        // 记录移动过程
        bool moved = false;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            std::cout << "  " << arr[j] << " 向右移动到位置 " << (j + 1) << std::endl;
            --j;
            moved = true;
        }

        arr[j + 1] = key;

        if (!moved) {
            std::cout << "  " << key << " 无需移动，已在正确位置" << std::endl;
        }

        std::cout << "  结果: ";
        printArray(arr);
        std::cout << std::endl << std::endl;
    }

    std::cout << std::string(50, '-') << std::endl;
    std::cout << "排序完成: ";
    printArray(arr);
    std::cout << std::endl;
}

/**
 * 二分插入排序 - 使用二分查找优化查找插入位置
 * 时间复杂度：比较次数 O(n log n)，但移动次数仍是 O(n²)
 * 对于比较操作代价高的场景（如字符串排序）更高效
 * @param arr 待排序的数组
 */
template <typename T>
void binaryInsertionSort(std::vector<T>& arr) {
    int n = arr.size();

    for (int i = 1; i < n; ++i) {
        T key = arr[i];

        // 使用二分查找确定插入位置
        int left = 0, right = i - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] > key) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        // left 现在是插入位置
        // 将 left 到 i-1 的元素都向后移动一位
        for (int j = i; j > left; --j) {
            arr[j] = arr[j - 1];
        }

        arr[left] = key;
    }
}

/**
 * 打印数组的辅助函数
 */
template <typename T>
void printArray(const std::vector<T>& arr) {
    std::cout << "[";
    for (size_t i = 0; i < arr.size(); ++i) {
        std::cout << arr[i];
        if (i < arr.size() - 1) {
            std::cout << ", ";
        }
    }
    std::cout << "]";
}

/**
 * 测试插入排序算法
 */
void testInsertionSort() {
    std::cout << std::string(60, '=') << std::endl;
    std::cout << "测试 1: 基本插入排序" << std::endl;
    std::cout << std::string(60, '=') << std::endl;

    std::vector<std::vector<int>> testCases = {
        {64, 34, 25, 12, 22, 11, 90},
        {1, 2, 3, 4, 5},      // 已排序
        {5, 4, 3, 2, 1},      // 逆序
        {1},                   // 单个元素
        {},                    // 空数组
        {3, 3, 3, 3}          // 全部相同
    };

    for (size_t i = 0; i < testCases.size(); ++i) {
        std::vector<int> original = testCases[i];
        insertionSort(testCases[i]);
        std::cout << "测试 " << i + 1 << ": ";
        printArray(original);
        std::cout << " -> ";
        printArray(testCases[i]);
        std::cout << std::endl;
    }

    std::cout << std::endl;
    std::cout << std::string(60, '=') << std::endl;
    std::cout << "测试 2: 带详细步骤的插入排序演示" << std::endl;
    std::cout << std::string(60, '=') << std::endl;

    std::vector<int> demoArr = {5, 2, 4, 6, 1, 3};
    insertionSortWithSteps(demoArr);

    std::cout << std::endl;
    std::cout << std::string(60, '=') << std::endl;
    std::cout << "测试 3: 二分插入排序" << std::endl;
    std::cout << std::string(60, '=') << std::endl;

    std::vector<int> testArr = {64, 34, 25, 12, 22, 11, 90};
    std::cout << "原始数组: ";
    printArray(testArr);
    std::cout << std::endl;

    binaryInsertionSort(testArr);
    std::cout << "排序结果: ";
    printArray(testArr);
    std::cout << std::endl;
}

int main() {
    testInsertionSort();
    return 0;
}"}
